	@Test
	public void testAlignedCallbackFailurePreventsCommit() throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
		File storeDir = new File(dataDir, "aligned-callback-failure");
		long[] baseline = { 719_999L, 17L, 18L, 19L };
		try (TripleStore store = new TripleStore(storeDir, config, null)) {
			store.startTransaction();
			store.storeTriple(baseline[0], baseline[1], baseline[2], baseline[3], true);
			store.commit();
			StatementBatch batch = createBatch(720_000L, 2);
			int[] callbackCalls = { 0 };
			store.startTransaction();
			assertThrows(IllegalStateException.class,
					() -> store.storeTriplesAligned(batch.subj, batch.pred, batch.obj, batch.context, batch.subj.length,
							true, ignored -> {
								callbackCalls[0]++;
								assertEquals(1, callbackCalls[0], "The failing callback must be invoked only once");
								throw new IllegalStateException("injected callback failure");
							}));
			assertThrows(IOException.class, store::commit,
					"A callback failure must not silently commit or discard a partially observed batch");
			assertEquals(1, callbackCalls[0], "The failing callback must be invoked exactly once");
			assertOnlyStoredQuad(store, baseline);
		}
		try (TripleStore reopened = new TripleStore(storeDir, config, null)) {
			assertOnlyStoredQuad(reopened, baseline);
		}
	}

