	@Test
	public void testReindexGrowthKeepsEveryEntryAcrossReopen() throws Exception {
		File reindexDir = new File(dataDir, "reindex-growth");
		StatementBatch batch = createBatch(900_000L, 12_000);
		Process reindexProcess = startReindexChild(reindexDir.toPath());
		try {
			assertTrue(reindexProcess.waitFor(120, TimeUnit.SECONDS),
					"The isolated reindex child must complete rather than hang on an invalid native cursor");
			String childOutput = new String(reindexProcess.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
			assertEquals(0, reindexProcess.exitValue(),
					"Reindex must complete without native failure; child output: " + childOutput);
		} finally {
			if (reindexProcess.isAlive()) {
				reindexProcess.destroyForcibly();
				reindexProcess.waitFor(10, TimeUnit.SECONDS);
			}
		}

		LmdbStoreConfig expandedConfig = new LmdbStoreConfig("spoc,posc,ospc,cspo");
		StoreProperties expandedProperties = new StoreProperties(reindexDir);
		assertTrue(expandedProperties.load());
		try (TripleStore reopened = new TripleStore(reindexDir, expandedProperties, expandedConfig, null);
				Txn txn = reopened.getTxnManager().createReadTxn()) {
			assertEquals(batch.subj.length, count(reopened.getTriples(txn, -1, -1, -1, -1, true)));
			assertEquals(expectedPredicateCount(batch, batch.pred[0]),
					count(reopened.getTriples(txn, -1, batch.pred[0], -1, -1, true)));
			assertEquals(1, count(reopened.getTriples(txn, -1, -1, batch.obj[batch.obj.length - 1], -1, true)));
			assertEquals(expectedContextCount(batch, batch.context[0]),
					count(reopened.getTriples(txn, -1, -1, -1, batch.context[0], true)));
		}
	}

	@Test
	public void testReindexRetryReopensDroppedDbiAfterAbort() throws Exception {
		File reindexDir = new File(dataDir, "reindex-dbi-retry");
		LmdbStoreConfig originalConfig = new LmdbStoreConfig("spoc,posc");
		originalConfig.setTripleDBSize(4096 * 10);
		StatementBatch batch = createBatch(920_000L, 256);
		StoreProperties originalProperties = new StoreProperties(reindexDir);
		try (TripleStore original = new TripleStore(reindexDir, originalProperties, originalConfig, null)) {
			original.startTransaction();
			storeBatch(original, batch, true, false);
			original.commit();
			originalProperties.save();
		}

		StoreProperties reindexProperties = new StoreProperties(reindexDir);
		assertTrue(reindexProperties.load());
		LmdbStoreConfig reindexConfig = new LmdbStoreConfig("spoc,cspo");
		reindexConfig.setTripleDBSize(4096 * 10);
		try (ReindexRetryTripleStore retried = new ReindexRetryTripleStore(reindexDir, reindexProperties,
				reindexConfig);
				Txn txn = retried.getTxnManager().createReadTxn()) {
			assertTrue(retried.injectedMapFull,
					"The first rebuild attempt must abort after the removed index handles were dropped");
			assertEquals(batch.subj.length, count(retried.getTriples(txn, -1, -1, -1, -1, true)));
			assertEquals(expectedPredicateCount(batch, batch.pred[0]),
					count(retried.getTriples(txn, -1, batch.pred[0], -1, -1, true)));
			assertEquals(1, count(retried.getTriples(txn, -1, -1, batch.obj[batch.obj.length - 1], -1, true)));
			assertEquals(expectedContextCount(batch, batch.context[0]),
					count(retried.getTriples(txn, -1, -1, -1, batch.context[0], true)));
		}

		StoreProperties reopenedProperties = new StoreProperties(reindexDir);
		assertTrue(reopenedProperties.load());
		try (TripleStore reopened = new TripleStore(reindexDir, reopenedProperties, reindexConfig, null);
				Txn txn = reopened.getTxnManager().createReadTxn()) {
			assertEquals(batch.subj.length, count(reopened.getTriples(txn, -1, -1, -1, -1, true)));
			assertEquals(1, count(reopened.getTriples(txn, batch.subj[0], batch.pred[0], batch.obj[0], batch.context[0],
					true)));
		}
	}

	@Test
	public void testFailedInferredIndexOpenDoesNotCloseSharedExplicitDbi() throws Exception {
		tripleStore.startTransaction();
		tripleStore.storeTriple(91L, 7L, 11L, 3L, true);
		tripleStore.commit();

		tripleStore.startTransaction();
		assertThrows(IOException.class, () -> new TripleIndex("spoc", "spoc", true, tripleStore.env,
				tripleStore.writeTxn, (txn, name, flags) -> {
					if (name.endsWith("-inf")) {
						throw new IOException("injected inferred-index open failure");
					}
					return LmdbUtil.openDatabaseWithTxn(txn, name, flags);
				}));
		tripleStore.rollback();

		try (Txn txn = tripleStore.getTxnManager().createReadTxn()) {
			assertEquals(1, count(tripleStore.getTriples(txn, 91L, 7L, 11L, 3L, true)),
					"A failed constructor must leave the existing shared explicit DBI usable");
		}
	}

