	@Test
	public void testFailedGrowthReplayRejectsCommitAndReleasesSpillFile() throws Exception {
		File replayDir = new File(dataDir, "failed-growth-replay");
		LmdbStoreConfig config = new LmdbStoreConfig("spoc");
		config.setTripleDBSize(4096 * 10);
		FailingReplayTripleStore store = new FailingReplayTripleStore(replayDir, config);
		long[] baseline = { 949_999L, 777L, 888L, 7L };
		IOException commitFailure = null;
		store.startTransaction();
		store.storeTriple(baseline[0], baseline[1], baseline[2], baseline[3], true);
		store.commit();
		long initialMapSize = mapSize(store);
		StatementBatch batch = createBatch(950_000L, batchSizeForMapGrowth(initialMapSize));
		store.startTransaction();
		IOException mutationFailure = assertThrows(IOException.class,
				() -> store.storeTriplesAligned(batch.subj, batch.pred, batch.obj, batch.context, batch.subj.length,
						true));
		assertTrue(mutationFailure.getMessage().contains("injected replay failure"));
		assertTrue(mapSize(store) > initialMapSize,
				"The test must reach a real LMDB map growth before injecting replay failure");
		assertTrue(replayJournalFiles(replayDir) > 0,
				"The large logical batch must spill its ordered replay journal before map growth");
		try {
			store.commit();
		} catch (IOException e) {
			commitFailure = e;
		} finally {
			store.rollback();
			store.close();
		}
		IOException capturedCommitFailure = commitFailure;
		assertAll("failed logical writer cleanup", () -> assertTrue(capturedCommitFailure != null,
				"Commit after a failed replay must report the stored logical failure"),
				() -> assertEquals(0, replayJournalFiles(replayDir),
						"Rollback or close must delete the spilled journal even without a native writer handle"));
		try (TripleStore reopened = new TripleStore(replayDir, config, null)) {
			assertOnlyStoredQuad(reopened, baseline);
		}
	}

	private static int replayJournalFiles(File dir) {
		File[] files = dir.listFiles((ignored, name) -> name.startsWith("txn-replay-") && name.endsWith(".bin"));
		return files == null ? 0 : files.length;
	}

	private static Process startReindexChild(Path dataDir) throws IOException {
		String javaBinary = Path.of(System.getProperty("java.home"), "bin", "java").toString();
		return new ProcessBuilder(javaBinary, "-cp", System.getProperty("java.class.path"),
				ReindexChild.class.getName(), dataDir.toString(), "12000")
						.redirectErrorStream(true)
						.start();
	}

	private static long expectedPredicateCount(StatementBatch batch, long predicate) {
		long count = 0;
		for (long value : batch.pred) {
			if (value == predicate) {
				count++;
			}
		}
		return count;
	}

	private static void assertPromotionThenRemovalIsBalanced(File dir, boolean aligned) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
		config.setTripleDBSize(4096 * 10);
		try (TripleStore store = new TripleStore(dir, config, null)) {
			StatementBatch batch = new StatementBatch(new long[] { 801, 802 }, new long[] { 803, 803 },
					new long[] { 804, 805 }, new long[] { 806, 806 });
			store.startTransaction();
			storeBatch(store, batch, false, aligned);
			store.commit();

			store.startTransaction();
			storeBatch(store, batch, true, aligned);
			store.commit();

			store.startTransaction();
			for (int i = 0; i < batch.subj.length; i++) {
				store.removeTriplesByContext(batch.subj[i], batch.pred[i], batch.obj[i], batch.context[i], true,
						ignored -> {
						});
			}
			store.commit();

			try (Txn txn = store.getTxnManager().createReadTxn()) {
				assertEquals(0, count(store.getTriples(txn, -1, -1, -1, -1, true)));
				assertEquals(0, count(store.getTriples(txn, -1, -1, -1, -1, false)));
				assertTrue(contextIds(store.getContexts(txn)).isEmpty(),
						"Removing promoted statements must clear their now-empty context");
			}
		}
	}

	private static void storeBatch(TripleStore store, StatementBatch batch, boolean explicit, boolean aligned)
			throws IOException {
		if (aligned) {
			store.storeTriplesAligned(batch.subj, batch.pred, batch.obj, batch.context, batch.subj.length, explicit);
		} else {
			for (int i = 0; i < batch.subj.length; i++) {
				store.storeTriple(batch.subj[i], batch.pred[i], batch.obj[i], batch.context[i], explicit);
			}
		}
	}

	@Test
	public void testMapGrowthReplayRegistersContextsForAlignedBatch() throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc,cspo,cpos,cosp");
		config.setTripleDBSize(512L * 1024);
		File storeDir = new File(dataDir, "aligned-bulk-journal-replay");
		StatementBatch batch;
		try (TripleStore store = new TripleStore(storeDir, config, null)) {
			long initialMapSize = mapSize(store);
			batch = createBatch(200_000L, batchSizeForMapGrowth(initialMapSize));
			int[] callbackCounts = new int[batch.subj.length];

			store.startTransaction();
			store.storeTriplesAligned(batch.subj, batch.pred, batch.obj, batch.context, batch.subj.length, true,
					index -> callbackCounts[index]++);
			assertDoesNotThrow(store::commit);
			assertTrue(mapSize(store) > initialMapSize,
					"The test must exercise the native auto-growth and complete journal replay path");
			for (int i = 0; i < callbackCounts.length; i++) {
				assertEquals(1, callbackCounts[i], "Each newly added statement callback must run once at index " + i);
			}
			assertBatchStoredWithContexts(store, batch);
		}

		try (TripleStore reopened = new TripleStore(storeDir, config, null)) {
			assertBatchStoredWithContexts(reopened, batch);
		}
	}

