	@Test
	public void testInferredPromotionKeepsContextCountsBalanced() throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
		File storeDir = new File(dataDir, "cached-inferred-promotion");
		try (TripleStore cachedStore = new TripleStore(storeDir, config, null)) {
			long subject = 101L;
			long predicate = 202L;
			long object = 303L;
			long context = 404L;

			cachedStore.startTransaction();
			assertTrue(cachedStore.storeTriple(subject, predicate, object, context, false));
			cachedStore.commit();

			cachedStore.startTransaction();
			assertTrue(cachedStore.storeTriple(subject, predicate, object, context, true));
			cachedStore.commit();

			cachedStore.startTransaction();
			cachedStore.removeTriplesByContext(subject, predicate, object, context, true, quad -> {
			});
			cachedStore.commit();

			try (Txn txn = cachedStore.getTxnManager().createReadTxn()) {
				assertEquals(0, count(cachedStore.getTriples(txn, -1, -1, -1, -1, true)));
				assertEquals(0, count(cachedStore.getTriples(txn, -1, -1, -1, -1, false)));
				assertTrue(contextIds(cachedStore.getContexts(txn)).isEmpty(),
						"Removing the promoted explicit statement should also clear the last context entry");
			}
		}
		try (TripleStore reopened = new TripleStore(storeDir, config, null);
				Txn txn = reopened.getTxnManager().createReadTxn()) {
			assertEquals(0, count(reopened.getTriples(txn, -1, -1, -1, -1, true)));
			assertEquals(0, count(reopened.getTriples(txn, -1, -1, -1, -1, false)));
			assertTrue(contextIds(reopened.getContexts(txn)).isEmpty(),
					"The final context removal must remain committed after reopen");
		}
	}

	@Test
	public void testDuplicateExplicitAddKeepsContextCountsBalanced() throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
		File storeDir = new File(dataDir, "cached-duplicate-explicit");
		try (TripleStore cachedStore = new TripleStore(storeDir, config, null)) {
			long subject = 501L;
			long predicate = 502L;
			long object = 503L;
			long context = 504L;

			cachedStore.startTransaction();
			assertTrue(cachedStore.storeTriple(subject, predicate, object, context, true));
			cachedStore.commit();

			cachedStore.startTransaction();
			assertFalse(cachedStore.storeTriple(subject, predicate, object, context, true),
					"Cached duplicate explicit add should not report a new statement");
			cachedStore.commit();

			cachedStore.startTransaction();
			cachedStore.removeTriplesByContext(subject, predicate, object, context, true, quad -> {
			});
			cachedStore.commit();

			try (Txn txn = cachedStore.getTxnManager().createReadTxn()) {
				assertEquals(0, count(cachedStore.getTriples(txn, -1, -1, -1, -1, true)));
				assertTrue(contextIds(cachedStore.getContexts(txn)).isEmpty(),
						"Deleting the last persisted statement should also clear the cached context entry");
			}
		}
		try (TripleStore reopened = new TripleStore(storeDir, config, null);
				Txn txn = reopened.getTxnManager().createReadTxn()) {
			assertEquals(0, count(reopened.getTriples(txn, -1, -1, -1, -1, true)));
			assertTrue(contextIds(reopened.getContexts(txn)).isEmpty(),
					"The final context removal must remain committed after reopen");
		}
	}

	private static long mapSize(TripleStore store) {
		try (var stack = stackPush()) {
			MDBEnvInfo info = MDBEnvInfo.malloc(stack);
			assertEquals(MDB_SUCCESS, mdb_env_info(store.env, info));
			return info.me_mapsize();
		}
	}

	private static List<Long> expectedContextIds(StatementBatch batch) {
		LinkedHashSet<Long> contextIds = new LinkedHashSet<>();
		for (long contextId : batch.context) {
			contextIds.add(contextId);
		}
		return new ArrayList<>(contextIds);
	}

	private static long expectedContextCount(StatementBatch batch, long contextId) {
		long count = 0;
		for (long batchContextId : batch.context) {
			if (batchContextId == contextId) {
				count++;
			}
		}
		return count;
	}

	private static List<Long> contextIds(LmdbContextIdIterator iterator) {
		List<Long> contextIds = new ArrayList<>();
		try (iterator) {
			long[] next;
			while ((next = iterator.next()) != null) {
				contextIds.add(next[0]);
			}
		}
		return contextIds;
	}

	private static void assertBatchStoredWithContexts(TripleStore store, StatementBatch batch) throws Exception {
		List<Long> expectedContextIds = expectedContextIds(batch);
		try (Txn txn = store.getTxnManager().createReadTxn()) {
			assertEveryBatchRecordPresent(store.getTriples(txn, -1, -1, -1, -1, true), batch);
			assertEquals(0, count(store.getTriples(txn, -1, -1, -1, -1, false)),
					"An explicit batch must not leave duplicate inferred records");
			assertEquals(expectedContextIds, contextIds(store.getContexts(txn)));
			for (long contextId : expectedContextIds) {
				assertEquals(expectedContextCount(batch, contextId),
						count(store.getTriples(txn, -1, -1, -1, contextId, true)));
			}
		}
	}

	private static void assertEveryBatchRecordPresent(RecordIterator records, StatementBatch batch) {
		boolean[] found = new boolean[batch.subj.length];
		int count = 0;
		try (records) {
			long[] record;
			while ((record = records.next()) != null) {
				int index = Math.toIntExact(record[0] - batch.subj[0]);
				assertTrue(index >= 0 && index < found.length, "An unexpected subject was committed: " + record[0]);
				assertFalse(found[index], "A batch record was committed more than once at index " + index);
				assertEquals(batch.subj[index], record[0], "Subject mismatch at batch index " + index);
				assertEquals(batch.pred[index], record[1], "Predicate mismatch at batch index " + index);
				assertEquals(batch.obj[index], record[2], "Object mismatch at batch index " + index);
				assertEquals(batch.context[index], record[3], "Context mismatch at batch index " + index);
				found[index] = true;
				count++;
			}
		}
		assertEquals(batch.subj.length, count, "The complete aligned batch must be committed exactly once");
		for (int i = 0; i < found.length; i++) {
			assertTrue(found[i], "The committed batch is missing record " + i);
		}
	}

	private static void assertOnlyStoredQuad(TripleStore store, long[] expected) throws Exception {
		try (Txn txn = store.getTxnManager().createReadTxn();
				RecordIterator records = store.getTriples(txn, -1, -1, -1, -1, true)) {
			long[] record = records.next();
			assertTrue(record != null, "The previously committed baseline statement must remain present");
			for (int i = 0; i < expected.length; i++) {
				assertEquals(expected[i], record[i], "Baseline quad field mismatch at position " + i);
			}
			assertTrue(records.next() == null, "No partial records from the failed transaction may be visible");
			assertEquals(0, count(store.getTriples(txn, -1, -1, -1, -1, false)),
					"Rollback must not leave inferred records from the failed transaction");
			assertEquals(List.of(expected[3]), contextIds(store.getContexts(txn)),
					"Rollback must preserve only the baseline context");
		}
	}

	private static StatementBatch createBatch(long baseId, int statementCount) {
		long[] subj = new long[statementCount];
		long[] pred = new long[statementCount];
		long[] obj = new long[statementCount];
		long[] context = new long[statementCount];
		for (int i = 0; i < statementCount; i++) {
			subj[i] = baseId + i;
			pred[i] = (i % 31) + 1L;
			obj[i] = baseId + 100_000L + i;
			context[i] = (i % 7) + 1L;
		}
		return new StatementBatch(subj, pred, obj, context);
	}

	private record StatementBatch(long[] subj, long[] pred, long[] obj, long[] context) {
	}

	public static final class ReindexChild {
		public static void main(String[] args) throws Exception {
			File dataDir = Path.of(args[0]).toFile();
			int size = Integer.parseInt(args[1]);
			StatementBatch batch = createBatch(900_000L, size);
			LmdbStoreConfig originalConfig = new LmdbStoreConfig("spoc");
			originalConfig.setTripleDBSize(4096 * 10);
			StoreProperties originalProperties = new StoreProperties(dataDir);
			try (TripleStore original = new TripleStore(dataDir, originalProperties, originalConfig, null)) {
				original.startTransaction();
				original.storeTriplesAligned(batch.subj, batch.pred, batch.obj, batch.context, batch.subj.length, true);
				original.commit();
				originalProperties.save();
			}

			LmdbStoreConfig expandedConfig = new LmdbStoreConfig("spoc,posc,ospc,cspo");
			expandedConfig.setTripleDBSize(4096 * 10);
			StoreProperties expandedProperties = new StoreProperties(dataDir);
			if (!expandedProperties.load()) {
				throw new IOException("The original index metadata must exist before reindex begins");
			}
			try (TripleStore expanded = new TripleStore(dataDir, expandedProperties, expandedConfig, null)) {
				expandedProperties.save();
			}
			System.out.println("REINDEX_CHILD_COMPLETE");
		}
	}

	private static final class ReindexRetryTripleStore extends TripleStore {
		private boolean injectedMapFull;

		private ReindexRetryTripleStore(File dir, StoreProperties properties, LmdbStoreConfig config)
				throws IOException {
			super(dir, properties, config, null);
		}

		@Override
		boolean commitReindexTransaction() throws IOException {
			if (!injectedMapFull) {
				injectedMapFull = true;
				mdb_txn_abort(writeTxn);
				writeTxn = 0;
				return false;
			}
			return super.commitReindexTransaction();
		}
	}

	private static final class FailingDropTripleIndex extends TripleIndex {
		private boolean failNextDrop = true;

		private FailingDropTripleIndex(String name, String fieldSeq, boolean createInferredIndex, long env,
				long writeTxn) throws IOException {
			super(name, fieldSeq, createInferredIndex, env, writeTxn);
		}

		@Override
		int dropDatabase(long txn, int dbi) {
			if (failNextDrop) {
				failNextDrop = false;
				return MDB_MAP_FULL;
			}
			return super.dropDatabase(txn, dbi);
		}
	}

	private static final class FailingReplayTripleStore extends TripleStore {
		private final File storeDir;
		private boolean failed;

		private FailingReplayTripleStore(File dir, LmdbStoreConfig config) throws IOException {
			super(dir, config, null);
			this.storeDir = dir;
		}

		@Override
		protected void afterMapGrowthReplay() throws IOException {
			if (!failed && replayJournalFiles(storeDir) > 0) {
				failed = true;
				throw new IOException("injected replay failure after growth");
			}
		}
	}

	private static final class FailingContextAlignedTripleStore extends TripleStore {
		private int incrementCalls;

		private FailingContextAlignedTripleStore(File dir, LmdbStoreConfig config) throws IOException {
			super(dir, config, null);
		}

		@Override
		void incrementAlignedContext(org.lwjgl.system.MemoryStack stack, long context, int amount) throws IOException {
			incrementCalls++;
			if (incrementCalls == 2) {
				throw new TripleStore.MapFullException();
			}
			super.incrementAlignedContext(stack, context, amount);
		}
	}

	private static final class FailingAlignedContextTripleStore extends TripleStore {
		private boolean failAfterFirstContextWrite = true;

		private FailingAlignedContextTripleStore(File dir, LmdbStoreConfig config) throws IOException {
			super(dir, config, null);
		}

		@Override
		void incrementAlignedContext(org.lwjgl.system.MemoryStack stack, long context, int amount) throws IOException {
			super.incrementAlignedContext(stack, context, amount);
			if (failAfterFirstContextWrite) {
				failAfterFirstContextWrite = false;
				throw new IOException("injected failure after the aligned main-index write");
			}
		}
	}

	private static int count(RecordIterator it) {
		int count = 0;
		try (it) {
			while (it.next() != null) {
				count++;
			}
		}
		return count;
	}

